import { scrollToValidationTarget } from '../../../../../utils/scrollToValidationTarget';
import type { BankTransferFormState } from './bankTransferMappers';

export type BankTransferFieldErrors = {
  voucherDate?: string;
  transferReasonCode?: string;
  fromBankAccountCode?: string;
  toBankAccountCode?: string;
  amount?: string;
  processingLevel?: string;
};

export function validateBankTransferFields(form: BankTransferFormState): {
  fieldErrors: BankTransferFieldErrors;
  bannerMessages: string[];
} {
  const fieldErrors: BankTransferFieldErrors = {};
  const bannerMessages: string[] = [];

  if (!form.voucherDate?.trim()) {
    const msg = 'Ngày chứng từ là bắt buộc';
    fieldErrors.voucherDate = msg;
    bannerMessages.push(msg);
  }

  if (!form.transferReasonCode?.trim()) {
    const msg = 'Loại chuyển là bắt buộc';
    fieldErrors.transferReasonCode = msg;
    bannerMessages.push(msg);
  }

  if (!form.fromBankAccountCode?.trim()) {
    const msg = 'Tài khoản đi là bắt buộc';
    fieldErrors.fromBankAccountCode = msg;
    bannerMessages.push(msg);
  }

  if (!form.toBankAccountCode?.trim()) {
    const msg = 'Tài khoản đến là bắt buộc';
    fieldErrors.toBankAccountCode = msg;
    bannerMessages.push(msg);
  }

  if (
    form.fromBankAccountCode?.trim()
    && form.toBankAccountCode?.trim()
    && form.fromBankAccountCode === form.toBankAccountCode
  ) {
    const msg = 'Tài khoản đi và tài khoản đến phải khác nhau';
    fieldErrors.toBankAccountCode = msg;
    bannerMessages.push(msg);
  }

  if (!(Number(form.amount) > 0)) {
    const msg = 'Số tiền chuyển phải lớn hơn 0';
    fieldErrors.amount = msg;
    bannerMessages.push(msg);
  }

  if (!form.processingLevel?.trim()) {
    const msg = 'Mức xử lý là bắt buộc';
    fieldErrors.processingLevel = msg;
    bannerMessages.push(msg);
  }

  return { fieldErrors, bannerMessages };
}

export function scrollToFirstBankTransferFieldError(
  fieldErrors: BankTransferFieldErrors,
  bannerId: string,
): void {
  const order: Array<keyof BankTransferFieldErrors> = [
    'voucherDate',
    'transferReasonCode',
    'fromBankAccountCode',
    'toBankAccountCode',
    'amount',
    'processingLevel',
  ];
  for (const key of order) {
    if (fieldErrors[key]) {
      scrollToValidationTarget(`kt-ctnb-field-${key}`, 80);
      return;
    }
  }
  scrollToValidationTarget(bannerId, 80);
}
