import type { BankInternalTransferDto, CashVoucherDto } from '../../../../../services/kt/models';

/** Map CTNB list DTO → shape for `VoucherSearchSlideout`. */
export function bankTransferToSearchRow(d: BankInternalTransferDto): CashVoucherDto {
  return {
    id: d.id,
    code: d.code,
    voucherDate: d.voucherDate,
    voucherType: d.transferReasonCode ?? '',
    receiptKind: '',
    customerName: d.counterpartyName ?? '',
    accountCode: d.fromAccountCode ?? d.fromBankAccountCode ?? '',
    description: d.description ?? '',
    amount: Number(d.amount) || 0,
    exchangeRate: 1,
    status: d.status,
    processingLevel: d.processingLevel ?? '',
    lines: [],
    createdAt: d.createdAt,
  };
}
